const say=(lang:"el"|"en",el:string,en:string)=>lang==="el"?el:en;

export function V33EscapeBuilderClient({slug,name,nameEn,trip,offers,lang="el",missionId=null}:Props){
 const[selected,setSelected]=useState<V8StayOffer|null>(offers[0]??null),[plan,setPlan]=useState<TripBuilderPlanV25|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState<string|null>(null),[email,setEmail]=useState(""),[mailState,setMailState]=useState<"idle"|"sending"|"sent"|"error">("idle");
 const destination=lang==="en"?nameEn:name,photo=selected?.imageUrl||selected?.thumbUrl||null,total=plan?.budgetBeyondHotel,guideUrl=plan?.guide.path||"",currentOffer=plan?.stay?.trackingUrl||selected?.trackingUrl||"",weatherSummary=useMemo(()=>plan?.weather.days.slice(0,5)??[],[plan]);

 async function persistCompleted(built:TripBuilderPlanV25){
  if(!missionId)return;
  const media=[built.stay?.imageUrl?{kind:"stay",url:built.stay.imageUrl}:null,...built.tripadvisor.places.map(x=>x.imageUrl?{kind:x.kind,url:x.imageUrl,name:x.name}:null),...built.tripadvisor.restaurants.map(x=>x.imageUrl?{kind:"restaurant",url:x.imageUrl,name:x.name}:null)].filter(Boolean).slice(0,20);
  await fetch("/api/escape/research/complete",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationId:slug,weather:built.weather,places:built.webResearch.bullets,restaurants:built.tripadvisor.restaurants,practicalNotes:built.webResearch.practicalNotes,logistics:{availability:built.availability,flexibleWindows:built.flexibleWindows,budgetBeyondHotel:built.budgetBeyondHotel},sources:built.webResearch.sources,media,guidePath:built.guide.path,trackingUrl:built.stay?.trackingUrl??selected?.trackingUrl??null})}).catch(()=>null);
 }
 async function build(){
  if(!selected)return;setBusy(true);setError(null);setPlan(null);
  try{
   if(missionId)await fetch("/api/escape/select",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationId:slug})}).catch(()=>null);
   const response=await fetch("/api/trip-builder",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({trip,slug,offerId:selected.sourceProductId})});if(!response.ok)throw new Error(`HTTP ${response.status}`);
   const built=await response.json() as TripBuilderPlanV25;setPlan(built);void persistCompleted(built);
  }catch(err){setError(err instanceof Error?err.message:say(lang,"Δεν μπόρεσα να επαληθεύσω το ταξίδι με ασφάλεια.","I could not verify the trip safely."))}finally{setBusy(false)}
 }
 async function sendEmail(event:FormEvent){event.preventDefault();if(!selected||!email)return;setMailState("sending");try{const response=await fetch("/api/guide/email",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({email,slug,start:trip.startDate,end:trip.endDate,offer:selected.sourceProductId,language:lang})});if(!response.ok)throw new Error();if(missionId)await fetch("/api/escape/email-state",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,email})}).catch(()=>null);setMailState("sent")}catch{setMailState("error")}}
 async function share(){const url=window.location.href,text=say(lang,`Τι λες για ${destination}; Δες την απόδραση που μας έφτιαξε ο AI travel expert.`,`What do you think about ${destination}? See the escape the AI travel expert built for us.`);if(navigator.share){await navigator.share({title:destination,text,url}).catch(()=>undefined)}else{await navigator.clipboard.writeText(url).catch(()=>undefined)}if(missionId)void fetch("/api/escape/event",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,eventName:"escape_shared",payload:{destinationId:slug}})}).catch(()=>null)}
 const track=(eventName:string,payload:Record<string,unknown>={})=>{if(missionId)void fetch("/api/escape/event",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,eventName,payload})}).catch(()=>null)};

 return <main className="escape-builder-v33">
  <section className="escape-builder-hero-v33" style={photo?{backgroundImage:`linear-gradient(90deg,rgba(4,12,20,.88),rgba(4,12,20,.35)),url('${photo}')`}:undefined}><a className="escape-back-v33" href={lang==="en"?"/en":"/"}>← {say(lang,"Νέα αναζήτηση","New search")}</a><div><span>YOUR ESCAPE · {trip.startDate} → {trip.endDate}</span><h1>{destination}</h1><p>{say(lang,"Εσύ διάλεξες τον προορισμό. Τώρα θα ελέγξουμε καιρό, πραγματικές επιλογές, τι αξίζει να δεις, φαγητό, μετακινήσεις και το budget γύρω από τη διαμονή — πριν σου πούμε να προχωρήσεις.","You chose the destination. Now we verify weather, real options, what is worth seeing, food, logistics and the budget around the stay — before asking you to proceed.")}</p></div></section>
  <section className="escape-builder-shell-v33">
   <div className="escape-builder-title-v33"><span>STEP 1</span><h2>{say(lang,"Διάλεξε τη βάση που θέλεις να ελέγξουμε.","Choose the base you want us to verify.")}</h2><p>{say(lang,"Δεν σε στέλνω ακόμη έξω από το site. Πρώτα χτίζω την πραγματική απόδραση γύρω από αυτή την επιλογή.","I am not sending you away yet. First I build the real escape around this option.")}</p></div>
   {offers.length?<div className="escape-offer-grid-v33">{offers.slice(0,6).map((offer,index)=><button type="button" key={offer.sourceProductId} className={selected?.sourceProductId===offer.sourceProductId?"is-active":""} onClick={()=>{setSelected(offer);setPlan(null)}}>{offer.imageUrl||offer.thumbUrl?<img src={offer.imageUrl||offer.thumbUrl||""} alt=""/>:null}<div><small>{index===0?say(lang,"Καλύτερο διαθέσιμο match","Best available match"):say(lang,"Εναλλακτική","Alternative")}</small><strong>{offer.propertyName}</strong><span>{offer.city||destination}</span>{offer.price!=null?<b>{offer.price.toLocaleString(lang==="el"?"el-GR":"en-GB")} {offer.currency||"EUR"}</b>:null}</div></button>)}</div>:<div className="escape-empty-v33">{say(lang,"Δεν υπάρχει ακόμη πλήρως έγκυρη διαμονή στο feed για όλο το διάστημα. Δεν θα κατασκευάσουμε ψεύτικη διαθεσιμότητα.","There is no fully valid stay in the feed for the whole period yet. We will not fabricate availability.")}</div>}
   <button className="escape-build-v33" type="button" onClick={build} disabled={!selected||busy}>{busy?say(lang,"Οι agents κάνουν 360° έλεγχο…","Agents are running the 360° check…"):say(lang,"Χτίσε την απόδρασή μου →","Build my escape →")}</button>{error?<div className="escape-error-v33">{error}</div>:null}
   {plan?<section className="escape-plan-v33"><div className="escape-builder-title-v33"><span>STEP 2 · 360° VERIFIED ESCAPE</span><h2>{say(lang,"Τώρα έχεις ταξίδι — όχι απλώς ένα δωμάτιο.","Now you have a trip — not just a room.")}</h2><p>{plan.webResearch.overview||say(lang,"Η πρόταση χτίστηκε μόνο από όσα μπορέσαμε να επαληθεύσουμε.","The proposal uses only what we could verify.")}</p></div>
    <div className="escape-plan-grid-v33"><article><span>WEATHER</span><h3>{plan.weather.label}</h3><div className="escape-weather-v33">{weatherSummary.map(day=><div key={day.date}><strong>{day.temperatureMinC==null?"?":Math.round(day.temperatureMinC)}–{day.temperatureMaxC==null?"?":Math.round(day.temperatureMaxC)}°</strong><small>{day.date.slice(5)}</small><p>{day.summary}</p></div>)}</div></article><article><span>{say(lang,"ΤΙ ΑΞΙΖΕΙ","WHAT IS WORTH IT")}</span><h3>{say(lang,"Μη χάσεις χρόνο στα λάθος πράγματα.","Do not waste time on the wrong things.")}</h3><ul>{plan.webResearch.bullets.slice(0,6).map(item=><li key={item.name}><strong>{item.name}</strong><p>{item.summary}</p></li>)}</ul></article></div>
    <div className="escape-plan-grid-v33"><article><span>FOOD & LOCAL LIFE</span><h3>{say(lang,"Επιλογές που έχουν λόγο να μπουν στο πρόγραμμα.","Places that deserve a place in the plan.")}</h3><div className="escape-place-list-v33">{plan.tripadvisor.restaurants.slice(0,5).map(item=><div key={item.locationId}>{item.imageUrl?<img src={item.imageUrl} alt=""/>:null}<div><strong>{item.name}</strong><small>{item.rating!=null?`${item.rating}/5 · `:""}{item.reviewCount!=null?`${item.reviewCount} reviews`:""}</small><p>{item.description}</p></div></div>)}{!plan.tripadvisor.restaurants.length?<p>{plan.tripadvisor.note}</p>:null}</div></article><article><span>{say(lang,"ΠΡΟΣΟΧΗ","WATCH OUT")}</span><h3>{say(lang,"Τι να ξέρεις πριν φύγεις.","What to know before you go.")}</h3><ul>{plan.webResearch.practicalNotes.slice(0,8).map((note,index)=><li key={index}><p>{note}</p></li>)}</ul>{total?<div className="escape-budget-v33"><strong>{say(lang,"Budget πέρα από τη διαμονή","Budget beyond the stay")}</strong><b>{total.totalLow}–{total.totalHigh} EUR</b><small>{total.note}</small></div>:null}</article></div>
    <section className="escape-final-card-v33"><div><span>{say(lang,"Η ΑΠΟΔΡΑΣΗ ΕΙΝΑΙ ΕΤΟΙΜΗ","YOUR ESCAPE IS READY")}</span><h2>{plan.stay?.propertyName}</h2><p>{say(lang,"Έλεγξες πρώτα το ταξίδι. Τώρα, αν σου κάνει, δες την τρέχουσα προσφορά στον πάροχο. Η τελική τιμή, δωμάτιο και διαθεσιμότητα επιβεβαιώνονται εκεί.","You checked the trip first. If it still feels right, view the current provider offer. Final price, room and availability are confirmed there.")}</p></div><div className="escape-actions-v33">{currentOffer?<a href={currentOffer} target="_blank" rel="sponsored nofollow noopener" onClick={()=>track("affiliate_offer_opened",{destinationId:slug,offerId:selected?.sourceProductId})}>{say(lang,"Δες την τρέχουσα προσφορά ↗","View current offer ↗")}</a>:null}{guideUrl?<a href={guideUrl} target="_blank" rel="noopener" onClick={()=>track("guide_downloaded",{destinationId:slug})}>{say(lang,"Κατέβασε το Escape Book PDF","Download Escape Book PDF")}</a>:null}<button type="button" onClick={share}>{say(lang,"Μοιράσου την πρόταση","Share this escape")}</button></div></section>
    <form className="escape-email-v33" onSubmit={sendEmail}><div><span>ESCAPE BOOK</span><h3>{say(lang,"Στείλε το προσωπικό travel dossier στο email σου.","Send the personal travel dossier to your email.")}</h3><p>{say(lang,"Με QR που οδηγεί στο ίδιο affiliate tracking URL. Δεν σε γράφουμε αυτόματα σε newsletter.","With a QR pointing to the same affiliate tracking URL. No automatic newsletter signup.")}</p></div><div><input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/><button disabled={mailState==="sending"}>{mailState==="sending"?say(lang,"Αποστολή…","Sending…"):say(lang,"Στείλε το Escape Book","Send Escape Book")}</button>{mailState==="sent"?<small>{say(lang,"Στάλθηκε.","Sent.")}</small>:mailState==="error"?<small>{say(lang,"Δεν στάλθηκε — χρησιμοποίησε το download.","Could not send — use the download instead.")}</small>:null}</div></form>
   </section>:null}
  </section>
 </main>
}

"use client";

import { FormEvent, useMemo, useState } from "react";
import type { V8RecommendationResponse } from "@/lib/decision/v8-types";

type Lang="el"|"en";
type DateWindow={id:string;labelEl:string;labelEn:string;noteEl:string;noteEn:string;start:string;end:string};
type Need={id:string;mood:string;energy:string;social:string;avoid:string;labelEl:string;labelEn:string;copyEl:string;copyEn:string};
type StreamRow={type:string;progress:number;message?:string;payload?:Record<string,unknown>};

const say=(lang:Lang,el:string,en:string)=>lang==="el"?el:en;
const iso=(d:Date)=>d.toISOString().slice(0,10);
const add=(d:Date,days:number)=>new Date(d.getTime()+days*86_400_000);
function nextWeekday(base:Date,weekday:number){const d=new Date(Date.UTC(base.getUTCFullYear(),base.getUTCMonth(),base.getUTCDate()));let delta=(weekday-d.getUTCDay()+7)%7;if(delta===0)delta=7;return add(d,delta)}
function buildDateWindows():DateWindow[]{const now=new Date(),friday=nextWeekday(now,5),nextFriday=add(friday,7),nextThursday=add(friday,6),saturday=nextWeekday(now,6);return[
 {id:"this-weekend",labelEl:"Αυτό το ΣΚ",labelEn:"This weekend",noteEl:"2 νύχτες · γρήγορη απόδραση",noteEn:"2 nights · quick reset",start:iso(friday),end:iso(add(friday,2))},
 {id:"next-weekend",labelEl:"Επόμενο ΣΚ",labelEn:"Next weekend",noteEl:"2 νύχτες · περισσότερο περιθώριο",noteEn:"2 nights · more choice",start:iso(nextFriday),end:iso(add(nextFriday,2))},
 {id:"long-weekend",labelEl:"Θέλω 3–4 μέρες",labelEn:"I want 3–4 days",noteEl:"Πέμπτη–Κυριακή · πραγματική ανάσα",noteEn:"Thu–Sun · a proper break",start:iso(nextThursday),end:iso(add(nextThursday,3))},
 {id:"week",labelEl:"Μία εβδομάδα",labelEn:"One week",noteEl:"7 νύχτες · πλήρης αποφόρτιση",noteEn:"7 nights · full reset",start:iso(saturday),end:iso(add(saturday,7))}
]}
const needs:Need[]=[
 {id:"switch-off",mood:"relax",energy:"restore",social:"quiet",avoid:"crowds",labelEl:"Θέλω να σβήσω",labelEn:"I need to switch off",copyEl:"Ήσυχα, εύκολα, χωρίς πρόγραμμα-μαραθώνιο.",copyEn:"Calm, easy and no itinerary marathon."},
 {id:"together",mood:"romantic",energy:"balanced",social:"quiet",avoid:"none",labelEl:"Χρειαζόμαστε χρόνο μαζί",labelEn:"We need time together",copyEl:"Όμορφες στιγμές, φαγητό, βόλτες, λίγη μαγεία.",copyEn:"Beautiful moments, food, walks and a little magic."},
 {id:"sun",mood:"warmth",energy:"restore",social:"balanced",avoid:"none",labelEl:"Χρειάζομαι ήλιο",labelEn:"I need sun",copyEl:"Ζεστότερη αίσθηση και όσο γίνεται λιγότερο ρίσκο εποχής.",copyEn:"Warmer feel with lower seasonal risk."},
 {id:"family",mood:"nature",energy:"balanced",social:"balanced",avoid:"long-travel",labelEl:"Να περάσουμε καλά με τα παιδιά",labelEn:"Make it easy with the kids",copyEl:"Λιγότερη ταλαιπωρία, περισσότερη ουσιαστική εμπειρία.",copyEn:"Less friction, more real family time."},
 {id:"adventure",mood:"adventure",energy:"stimulating",social:"balanced",avoid:"none",labelEl:"Θέλω κάτι που θα θυμάμαι",labelEn:"I want something memorable",copyEl:"Διαφορετικό, ζωντανό, όχι άλλη μία προβλέψιμη απόδραση.",copyEn:"Different, vivid and not another predictable escape."},
 {id:"spoil",mood:"food",energy:"balanced",social:"lively",avoid:"none",labelEl:"Θέλω να καλοπεράσω",labelEn:"I want to feel spoiled",copyEl:"Καλό φαγητό, ωραία ατμόσφαιρα και αίσθηση ότι άξιζε.",copyEn:"Great food, atmosphere and a feeling it was worth it."}
];
function groupSize(type:string){return type==="solo"?1:type==="couple"?2:4}

export function V33EscapeFunnel({lang="el"}:{lang?:Lang}){
 const windows=useMemo(buildDateWindows,[]),[windowId,setWindowId]=useState(windows[0]?.id??"this-weekend"),[needId,setNeedId]=useState(needs[0].id),[travelerType,setTravelerType]=useState("couple"),[origin,setOrigin]=useState("Athens"),[budget,setBudget]=useState(900),[tripText,setTripText]=useState(""),[rows,setRows]=useState<StreamRow[]>([]),[result,setResult]=useState<V8RecommendationResponse|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState<string|null>(null),[missionId,setMissionId]=useState<string|null>(null);
 const selectedWindow=windows.find(x=>x.id===windowId)??windows[0],selectedNeed=needs.find(x=>x.id===needId)??needs[0],progress=rows.at(-1)?.progress??0;

 async function createMission(needText:string){
  if(!selectedWindow||!selectedNeed)return null;
  try{const response=await fetch("/api/escape/mission",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({locale:lang,originText:origin,travelWindow:{label:say(lang,selectedWindow.labelEl,selectedWindow.labelEn),start:selectedWindow.start,end:selectedWindow.end},needText,travelerType,groupSize:groupSize(travelerType),budgetEur:budget,dna:[selectedNeed.id,selectedNeed.mood,selectedNeed.energy,selectedNeed.social]})});if(!response.ok)return null;const data=await response.json() as {missionId?:string};return data.missionId??null}catch{return null}
 }
 async function persistFinalists(id:string,finalResult:V8RecommendationResponse){
  const finalists=finalResult.recommendations.slice(0, 3).map(x=>({slug:x.slug,score:x.score,why:x.why,seasonNote:x.seasonNote,budgetLabel:x.budgetLabel,effortLabel:x.effortLabel}));
  await fetch("/api/escape/matches",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId:id,finalists})}).catch(()=>null);
 }
 async function solve(event:FormEvent){
  event.preventDefault();if(!selectedWindow||!selectedNeed)return;setBusy(true);setRows([]);setResult(null);setError(null);setMissionId(null);
  const startMs=Date.parse(`${selectedWindow.start}T00:00:00Z`),endMs=Date.parse(`${selectedWindow.end}T00:00:00Z`),needText=tripText.trim()||say(lang,selectedNeed.copyEl,selectedNeed.copyEn),createdMissionId=await createMission(needText);setMissionId(createdMissionId);
  const payload={origin,startDate:selectedWindow.start,endDate:selectedWindow.end,month:"flexible",nights:Math.max(1,Math.round((endMs-startMs)/86_400_000)),budget,travelerType,groupSize:groupSize(travelerType),moods:[selectedNeed.mood],language:lang,distancePreference:"any",pace:selectedNeed.energy==="restore"?"slow":"balanced",hotelStyle:"any",avoid:selectedNeed.avoid,entryMode:"unknown",desiredEnergy:selectedNeed.energy,socialPreference:selectedNeed.social,noveltyPreference:needId==="adventure"?"surprise":"balanced",mustHave:needId==="sun"?"sea":"none",dateFlexibility:"few-days",transportMode:"any",stayLocationPreference:"balanced",tripText:needText};
  try{const response=await fetch("/api/recommend/stream",{method:"POST",headers:{"content-type":"application/json",accept:"application/x-ndjson"},body:JSON.stringify(payload)});if(!response.ok)throw new Error(`HTTP ${response.status}`);const reader=response.body?.getReader();if(!reader)throw new Error("stream unavailable");const decoder=new TextDecoder();let buffer="";while(true){const{done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split("\n");buffer=lines.pop()||"";for(const line of lines){if(!line.trim())continue;const item=JSON.parse(line) as StreamRow&{result?:V8RecommendationResponse};if(item.type==="final"&&item.result){setResult(item.result);if(createdMissionId)void persistFinalists(createdMissionId,item.result)}else setRows(current=>[...current,item])}}}catch(err){setError(err instanceof Error?err.message:say(lang,"Δεν ολοκληρώθηκε η ανάλυση.","Analysis did not complete."))}finally{setBusy(false)}
 }
 const shortlist=result?.recommendations.slice(0, 3)??[],labels=[say(lang,"Η επιλογή μου","The one I'd pick"),say(lang,"Η έξυπνη αξία","Smart value"),say(lang,"Η απρόσμενη","The wildcard")];
 return <main className="escape-v33">
  <section className="escape-hero-v33"><div className="escape-nav-v33"><a href={lang==="en"?"/en":"/"} className="escape-brand-v33">AI TRAVEL <span>ESCAPE</span></a><a href={lang==="en"?"/":"/en"}>{lang==="en"?"Ελληνικά":"English"}</a></div><div className="escape-hero-grid-v33"><div><span className="escape-kicker-v33">AI HOLIDAY SOLVER · DATE → FEELING → FIT</span><h1>{say(lang,"Δεν χρειάζεται να ξέρεις πού θέλεις να πας.","You don't need to know where you want to go.")}</h1><p>{say(lang,"Πες μου πότε μπορείς να φύγεις και τι χρειάζεσαι πραγματικά από αυτή την απόδραση. Θα περιορίσω τον κόσμο στις 3 επιλογές που βγάζουν περισσότερο νόημα για εσένα.","Tell me when you can leave and what you actually need from this break. I’ll narrow the world to three escapes that make the most sense for you.")}</p></div><div className="escape-orbit-v33"><div className="escape-orbit-core-v33">YOUR<br/>ESCAPE</div><span>DATE</span><span>MOOD</span><span>WEATHER</span><span>VALUE</span></div></div></section>
