  </form>
  {(busy||rows.length>0)&&!result?<section className="escape-investigation-v33"><div><span>AI MISSION</span><strong>{Math.min(100,progress)}%</strong></div><div className="escape-progress-v33"><i style={{width:`${Math.min(100,progress)}%`}}/></div><p>{rows.at(-1)?.message||say(lang,"Οι agents αποκλείουν επιλογές που δεν αξίζουν τον χρόνο σου.","The agents are eliminating options that do not deserve your time.")}</p></section>:null}
  {error?<section className="escape-error-v33">{error}</section>:null}
  {result?<section className="escape-results-v33"><div className="escape-result-intro-v33"><span className="escape-kicker-v33">MISSION SHORTLIST</span><h2>{say(lang,"Τρεις επιλογές επέζησαν.","Three escapes survived.")}</h2><p>{result.profileSummary}</p></div><div className="escape-result-grid-v33">{shortlist.map((item,index)=>{const query=new URLSearchParams({start:selectedWindow.start,end:selectedWindow.end,budget:String(budget),travelerType,mood:selectedNeed.mood,origin,lang});if(missionId)query.set("mission",missionId);return <article key={item.slug} className={index===0?"is-winner":""}><span>{labels[index]}</span><div className="escape-score-v33">{item.score}<small>/100</small></div><h3>{lang==="en"?item.destinationEn:item.destination}</h3><p>{item.why}</p><div className="escape-trade-v33"><strong>{say(lang,"Γιατί τώρα","Why now")}</strong><span>{item.seasonNote}</span></div><div className="escape-tags-v33">{item.tags.slice(0,4).map(tag=><i key={tag}>{tag}</i>)}</div><a href={`/escape/${item.slug}?${query.toString()}`}>{say(lang,"Ναι — χτίσε αυτή την απόδραση","Yes — build this escape")}</a></article>})}</div></section>:null}
 </main>
}

