const groupSize=(type:Profile["travelerType"])=>type==="solo"?1:type==="couple"?2:4;
function nextWeekday(base:Date,weekday:number,weekOffset=0){const d=new Date(Date.UTC(base.getUTCFullYear(),base.getUTCMonth(),base.getUTCDate()));const delta=(weekday-d.getUTCDay()+7)%7||7;return add(d,delta+weekOffset*7)}

const VISUAL_WORLDS:VisualWorld[]=[
 {id:"sea-light",query:"Mediterranean island aerial coast",el:"Θάλασσα & φως",en:"Sea & light",hintEl:"Ορίζοντας, νερό, αργός ρυθμός.",hintEn:"Horizon, water, slower rhythm.",semanticEl:"Με τραβάει η θάλασσα, το φως και ένας αργός μεσογειακός ρυθμός.",semanticEn:"I am drawn to sea, light and a slower Mediterranean rhythm."},
