 {id:"easy",label:say(lang,"Εύκολη απόδραση","Easy escape"),note:say(lang,"Παρασκευή · λίγη άδεια","Friday · minimal leave"),start:iso(fri),end:iso(add(fri,duration)),reason:say(lang,"Χαμηλή οργανωτική τριβή.","Low planning friction."),confidence:"MEDIUM"},
 {id:"space",label:say(lang,"Περισσότερος χώρος","More room"),note:say(lang,"Λίγο αργότερα · περισσότερες επιλογές","A little later · more options"),start:iso(fri2),end:iso(add(fri2,duration)),reason:say(lang,"Μεγαλύτερο περιθώριο για δυνατό matching.","More room for stronger matching."),confidence:"MEDIUM"},
 {id:"quiet",label:say(lang,"Πιο ήσυχος ρυθμός","Quieter rhythm"),note:say(lang,"Κυριακή–μέσα εβδομάδας","Sunday into midweek"),start:iso(sun),end:iso(add(sun,duration)),reason:say(lang,"Λιγότερη πίεση από weekend patterns.","Less weekend-pattern pressure."),confidence:"MEDIUM"}
]}

export function V34EscapeFunnel({lang="el"}:{lang?:Lang}){
 const[stage,setStage]=useState<Stage>("feel"),[initialText,setInitialText]=useState(""),[activeWorld,setActiveWorld]=useState("sea-light"),[answers,setAnswers]=useState<Answer[]>([]),[discovery,setDiscovery]=useState<Discovery|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState<string|null>(null);
 const[dateMode,setDateMode]=useState<"suggest"|"fixed"|"flexible">("suggest"),[duration,setDuration]=useState(3),[horizonDays,setHorizonDays]=useState(60),[dateWindows,setDateWindows]=useState<DateWindow[]>(()=>fallbackWindows(lang,3)),[windowId,setWindowId]=useState("easy"),[dateLoading,setDateLoading]=useState(false);
 const initialFallback=useMemo(()=>fallbackWindows(lang,3)[0],[lang]);
 const[fixedStart,setFixedStart]=useState(initialFallback.start),[fixedEnd,setFixedEnd]=useState(initialFallback.end),[origin,setOrigin]=useState(say(lang,"Αθήνα","Athens")),[budget,setBudget]=useState(1200),[rows,setRows]=useState<StreamRow[]>([]),[result,setResult]=useState<EscapeSolutionResponseV35|null>(null),[solutionIndex,setSolutionIndex]=useState(0),[missionId,setMissionId]=useState<string|null>(null);
 const[moodMedia,setMoodMedia]=useState<Record<string,Media>>({}),[solutionMedia,setSolutionMedia]=useState<Record<string,Media[]>>({});
 const selectedWindow=dateMode==="fixed"?{id:"fixed",label:say(lang,"Οι ημερομηνίες μου","My dates"),note:"",start:fixedStart,end:fixedEnd}:dateWindows.find(item=>item.id===windowId)??dateWindows[0];
 const q=discovery?.nextQuestionId?QUESTIONS[discovery.nextQuestionId]:null,solutions=result?.solutions??[],selectedSolution=solutions[solutionIndex]??null,activeWorldMedia=moodMedia[activeWorld];
 const step=stage==="feel"?1:stage==="questions"||stage==="dna"?2:stage==="dates"?3:stage==="reality"?4:5;

 useEffect(()=>{let cancelled=false;Promise.all(VISUAL_WORLDS.map(async world=>{try{const r=await fetch(`/api/escape/media?mode=aerial&destination=${encodeURIComponent(world.query)}`);const d=await r.json() as {items?:Media[]};return[world.id,d.items?.[0]??null] as const}catch{return[world.id,null] as const}})).then(entries=>{if(cancelled)return;const next:Record<string,Media>={};for(const[id,item]of entries)if(item)next[id]=item;setMoodMedia(next)});return()=>{cancelled=true}},[]);
 useEffect(()=>{if(stage!=="dates"||!discovery||dateMode==="fixed")return;let cancelled=false;setDateLoading(true);fetch("/api/escape/date-opportunities",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({locale:lang,initialText,duration,horizonDays:dateMode==="flexible"?horizonDays:60,profile:{travelerType:discovery.profile.travelerType,desiredEnergy:discovery.profile.desiredEnergy,socialPreference:discovery.profile.socialPreference,noveltyPreference:discovery.profile.noveltyPreference,avoid:discovery.profile.avoid,moods:discovery.profile.moods}})}).then(async r=>r.ok?await r.json():null).then((d:{windows?:DateWindow[]}|null)=>{if(cancelled)return;const windows=d?.windows?.length===3?d.windows:fallbackWindows(lang,duration);setDateWindows(windows);setWindowId(windows[0].id)}).catch(()=>{if(!cancelled){const windows=fallbackWindows(lang,duration);setDateWindows(windows);setWindowId(windows[0].id)}}).finally(()=>{if(!cancelled)setDateLoading(false)});return()=>{cancelled=true}},[stage,discovery,dateMode,duration,horizonDays,initialText,lang]);
 useEffect(()=>{if(!solutions.length)return;let cancelled=false;Promise.all(solutions.map(async solution=>{const destination=solution.recommendation.destinationEn||solution.recommendation.destination;try{const r=await fetch(`/api/escape/media?mode=aerial&destination=${encodeURIComponent(destination)}`);const d=await r.json() as {items?:Media[]};return[solution.recommendation.slug,d.items?.slice(0,4)??[]] as [string,Media[]]}catch{return[solution.recommendation.slug,[] as Media[]] as [string,Media[]]}})).then(entries=>{if(cancelled)return;const next:Record<string,Media[]>={};for(const[slug,items]of entries)next[slug]=items;setSolutionMedia(next)});return()=>{cancelled=true}},[result]);

 function chooseVisual(world:VisualWorld){setActiveWorld(world.id);const semantic=say(lang,world.semanticEl,world.semanticEn);setInitialText(current=>current.includes(semantic)?current:(current.trim()?`${current.trim()} ${semantic}`:semantic))}
 async function discover(nextAnswers=answers){setBusy(true);setError(null);try{const r=await fetch("/api/escape/discovery",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({locale:lang,initialText,answers:nextAnswers})});if(!r.ok)throw new Error();const d=await r.json() as Discovery;setDiscovery(d);setStage(d.complete?"dna":"questions")}catch{setError(say(lang,"Δεν κατάφερα να σε καταλάβω αρκετά. Δοκίμασε ξανά με λίγες περισσότερες λέξεις.","I could not understand enough yet. Try again with a little more detail."))}finally{setBusy(false)}}
 async function start(e:FormEvent){e.preventDefault();if(initialText.trim().length<3)return;await discover([])}
 async function answer(questionId:QuestionId,value:string){const next=[...answers.filter(a=>a.questionId!==questionId),{questionId,value}];setAnswers(next);await discover(next)}
 async function createMission(){if(!discovery||!selectedWindow)return null;try{const r=await fetch("/api/escape/mission",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({locale:lang,originText:origin,travelWindow:{label:selectedWindow.label,start:selectedWindow.start,end:selectedWindow.end},needText:initialText.slice(0,500),travelerType:discovery.profile.travelerType,groupSize:groupSize(discovery.profile.travelerType),budgetEur:budget,dna:discovery.profile.dnaLabels})});if(!r.ok)return null;const d=await r.json() as {missionId?:string};return d.missionId??null}catch{return null}}
 async function persistSolutions(id:string,finalResult:EscapeSolutionResponseV35){const finalists=finalResult.solutions.slice(0,10).map(item=>({slug:item.recommendation.slug,score:item.combinedScore,why:`${item.reasoning.destination} ${item.reasoning.stay}`,seasonNote:item.recommendation.seasonNote,budgetLabel:item.recommendation.budgetLabel,effortLabel:item.recommendation.effortLabel}));await fetch("/api/escape/matches",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId:id,finalists})}).catch(()=>null)}
 async function solve(){if(!discovery||!selectedWindow)return;setBusy(true);setError(null);setRows([]);setResult(null);setSolutionIndex(0);setStage("solve");const id=await createMission();setMissionId(id);const nights=Math.max(1,Math.round((Date.parse(`${selectedWindow.end}T00:00:00Z`)-Date.parse(`${selectedWindow.start}T00:00:00Z`))/DAY));const payload={origin,startDate:selectedWindow.start,endDate:selectedWindow.end,month:"flexible",nights,budget,moods:discovery.profile.moods.length?discovery.profile.moods:["relax"],travelerType:discovery.profile.travelerType,groupSize:groupSize(discovery.profile.travelerType),language:lang,distancePreference:"any",pace:discovery.profile.pace,hotelStyle:"any",avoid:discovery.profile.avoid,entryMode:"idea",desiredEnergy:discovery.profile.desiredEnergy,socialPreference:discovery.profile.socialPreference,noveltyPreference:discovery.profile.noveltyPreference,mustHave:discovery.profile.mustHave,dateFlexibility:dateMode==="fixed"?"fixed":"few-days",transportMode:"any",stayLocationPreference:"balanced",tripText:`${initialText}. ${discovery.summary}`.slice(0,500)};
  try{const response=await fetch("/api/escape/solve/stream",{method:"POST",headers:{"content-type":"application/json",accept:"application/x-ndjson"},body:JSON.stringify(payload)});if(!response.ok)throw new Error();const reader=response.body?.getReader();if(!reader)throw new Error();const decoder=new TextDecoder();let buffer="";const consume=(line:string)=>{if(!line.trim())return;const item=JSON.parse(line) as StreamRow&{result?:EscapeSolutionResponseV35};if(item.type==="final"&&item.result){setResult(item.result);setStage("results");if(id)void persistSolutions(id,item.result)}else if(item.type==="continuity"){setError(item.message??say(lang,"Δεν βρήκα ασφαλές αποτέλεσμα. Δοκίμασε πιο ανοιχτό budget ή ημερομηνίες.","I could not find a safe result. Try wider dates or budget."))}else setRows(current=>[...current,item])};while(true){const{done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});const lines=buffer.split("\n");buffer=lines.pop()||"";for(const line of lines)consume(line)}if(buffer.trim())consume(buffer)}catch{setError(say(lang,"Η ανάλυση δεν ολοκληρώθηκε. Κράτησα το προφίλ σου για να ξαναδοκιμάσεις.","The analysis did not complete. I kept your profile so you can retry."));setStage("reality")}finally{setBusy(false)}}
 function reset(){setStage("feel");setResult(null);setRows([]);setError(null);setSolutionIndex(0)}
 function tripHref(solution:EscapeSolutionV35){const rec=solution.recommendation;return `/escape/${encodeURIComponent(rec.slug)}?start=${selectedWindow?.start}&end=${selectedWindow?.end}&budget=${budget}&travelerType=${discovery?.profile.travelerType??"couple"}&mood=${discovery?.profile.moods[0]??"relax"}&origin=${encodeURIComponent(origin)}&lang=${lang}&offer=${encodeURIComponent(solution.stay.sourceProductId)}${missionId?`&mission=${missionId}`:""}`}
 function moveSolution(delta:number){if(!solutions.length)return;setSolutionIndex(current=>(current+delta+solutions.length)%solutions.length)}
 const selectedGallery=selectedSolution?solutionMedia[selectedSolution.recommendation.slug]??[]:[],selectedBackdrop=selectedGallery[0]?.imageUrl??selectedSolution?.stay.imageUrl??activeWorldMedia?.imageUrl??null;

 return <main className={styles.shell} data-mood={activeWorld} data-stage={stage}>
  {selectedBackdrop&&stage==="results"?<img key={`${selectedSolution?.recommendation.slug}-backdrop`} className={styles.globalBackdrop} src={selectedBackdrop} alt="" aria-hidden="true"/>:activeWorldMedia?<img key={`${activeWorld}-backdrop`} className={styles.globalBackdrop} src={activeWorldMedia.imageUrl} alt="" aria-hidden="true"/>:<div className={styles.globalFallback}/>}<div className={styles.globalShade}/><div className={styles.grain}/>
  <header className={styles.topbar}><button type="button" className={styles.brand} onClick={reset}>AI TRAVEL <b>ESCAPE</b></button><div className={styles.steps}>{[1,2,3,4,5].map(n=><span key={n} className={n===step?styles.stepActive:n<step?styles.stepDone:""}>{n}</span>)}</div><a className={styles.lang} href={lang==="en"?"/":"/en"}>{lang==="en"?"ΕΛ":"EN"}</a></header>

  {stage==="feel"&&<section className={styles.stage}><div className={styles.heroCopy}><span className={styles.eyebrow}>01 · FEEL FIRST</span><h1>{say(lang,"Πώς θέλεις να νιώθεις όταν φύγεις;","How do you want to feel when you leave?")}</h1><p>{say(lang,"Μην ψάξεις προορισμό. Δώσε μου το πρόβλημα, το mood ή απλώς διάλεξε μια εικόνα.","Do not search for a destination. Give me the problem, the mood, or simply choose an image.")}</p><form onSubmit={start} className={styles.prompt}><textarea value={initialText} onChange={e=>setInitialText(e.target.value)} placeholder={say(lang,"π.χ. Έχω κουραστεί, θέλω 4 μέρες με τη σύντροφό μου, ήσυχα αλλά με καλό φαγητό…","e.g. I am exhausted. Four days with my partner, calm but with great food…")} maxLength={700}/><button disabled={busy||initialText.trim().length<3}>{busy?"AI…":say(lang,"Ξεκίνα →","Start →")}</button></form></div><div className={styles.moodDeck}>{VISUAL_WORLDS.map(world=>{const media=moodMedia[world.id];return <button key={world.id} type="button" className={activeWorld===world.id?styles.moodActive:""} onClick={()=>chooseVisual(world)}>{media&&<img src={media.imageUrl} alt=""/>}<i/><strong>{say(lang,world.el,world.en)}</strong><small>{say(lang,world.hintEl,world.hintEn)}</small></button>})}</div></section>}

