  {backdrop?<img key={`${stage}-${activeWorld}-${solutionIndex}-${frame}`} className={styles.backdrop} src={backdrop} alt="" aria-hidden="true"/>:<div className={styles.fallback}/>}<div className={styles.shade}/><div className={styles.grain}/>
  <header className={styles.topbar}><button className={styles.brand} onClick={reset}>AI TRAVEL <b>ESCAPE</b></button><div className={styles.progress}>{[1,2,3,4,5].map(n=><span key={n} className={n===step?styles.active:n<step?styles.done:""}>{n}<i/></span>)}</div><a className={styles.lang} href={lang==="en"?"/":"/en"}>{lang==="en"?"ΕΛ":"EN"}</a></header>

  {stage==="mood"&&<section className={styles.screen}><div className={styles.hero}><span className={styles.kicker}>01 · MOOD</span><h1>{say(lang,"Μην μου πεις πού. Πες μου τι χρειάζεσαι.","Do not tell me where. Tell me what you need.")}</h1><p>{say(lang,"Δώσε μου το πρόβλημα ή διάλεξε την εικόνα που σε τραβάει. Από εκεί ξεκινά η απόφαση.","Give me the problem or choose the image that pulls you. That is where the decision starts.")}</p><form className={styles.prompt} onSubmit={start}><textarea value={initialText} onChange={e=>setInitialText(e.target.value)} placeholder={say(lang,"π.χ. Είμαι κουρασμένος, 4 μέρες με τη σύντροφό μου, ήσυχα αλλά με καλό φαγητό…","e.g. Exhausted, four days with my partner, quiet but with great food…")} maxLength={700}/><button disabled={busy||initialText.trim().length<3}>{say(lang,"Κατάλαβέ με →","Understand me →")}</button></form></div><div className={styles.worlds}>{WORLDS.map(world=>{const image=moodMedia[world.id]?.[frame%(moodMedia[world.id]?.length||1)]?.imageUrl;return <button key={world.id} className={activeWorld===world.id?styles.worldActive:""} onClick={()=>chooseWorld(world)}>{image&&<img src={image} alt=""/>}<i/><strong>{say(lang,world.el,world.en)}</strong><small>{say(lang,world.hintEl,world.hintEn)}</small></button>})}</div></section>}

  {stage==="dna"&&<section className={styles.screen}>{!discovery?<div className={styles.center}><div className={styles.pulse}/><h2>{say(lang,"Σε ακούω…","Listening…")}</h2></div>:q&&!discovery.complete?<><div className={styles.context}><span className={styles.kicker}>02 · TRAVELER DNA</span><p>{discovery.summary}</p><small>{say(lang,"Ρωτάω μόνο ό,τι μπορεί να αλλάξει πραγματικά την επιλογή.","I only ask what can genuinely change the choice.")}</small></div><div className={styles.question}><h2>{say(lang,q.el,q.en)}</h2><div className={styles.choices}>{q.options.map(option=><button key={option.value} disabled={busy} onClick={()=>answer(discovery.nextQuestionId!,option.value)}><b>{say(lang,option.el,option.en)}</b><span>{say(lang,option.hintEl,option.hintEn)}</span></button>)}</div></div></>:<div className={styles.dnaCard}><span className={styles.kicker}>02 · ESCAPE DNA</span><h2>{say(lang,"Αυτό είναι που κατάλαβα ότι χρειάζεσαι.","This is what I think you actually need.")}</h2><blockquote>{discovery.summary}</blockquote><div className={styles.dnaChips}>{discovery.profile.dnaLabels.map(label=><span key={label}>{label}</span>)}</div><div className={styles.actions}><button className={styles.primary} onClick={()=>setStage("time")}>{say(lang,"Σωστά — βρες πότε →","Correct — find when →")}</button><button className={styles.secondary} onClick={()=>setStage("mood")}>{say(lang,"Όχι ακριβώς","Not quite")}</button></div></div>}</section>}

  {stage==="time"&&discovery&&<section className={styles.screen}><div className={styles.timeHead}><span className={styles.kicker}>03 · TIME</span><h2>{say(lang,"Πότε έχει νόημα να φύγεις;","When does it make sense to go?")}</h2><div className={styles.modes}>{(["suggest","fixed","flexible"] as const).map(mode=><button key={mode} className={dateMode===mode?styles.modeActive:""} onClick={()=>setDateMode(mode)}>{mode==="suggest"?say(lang,"Βρες το για μένα","Find it for me"):mode==="fixed"?say(lang,"Ξέρω πότε","I know when"):say(lang,"Είμαι flexible","I am flexible")}</button>)}</div></div>{dateMode==="fixed"?<div className={styles.fixed}><label>{say(lang,"Αναχώρηση","Departure")}<input type="date" value={fixedStart} min={iso(new Date())} onChange={e=>setFixedStart(e.target.value)}/></label><label>{say(lang,"Επιστροφή","Return")}<input type="date" value={fixedEnd} min={fixedStart} onChange={e=>setFixedEnd(e.target.value)}/></label></div>:<div className={styles.timeBody}><div className={styles.pills}><span>{say(lang,"Νύχτες","Nights")}</span>{[2,3,4,5,7].map(n=><button key={n} className={duration===n?styles.pillActive:""} onClick={()=>setDuration(n)}>{n}</button>)}{dateMode==="flexible"&&[60,90,120].map(n=><button key={n} className={horizonDays===n?styles.pillActive:""} onClick={()=>setHorizonDays(n)}>{n}d</button>)}</div><div className={styles.windows}>{dateLoading?<div className={styles.loading}>{say(lang,"Ο Date Agent ψάχνει 3 λογικά παράθυρα…","The Date Agent is finding three sensible windows…")}</div>:dateWindows.map(w=><button key={w.id} className={windowId===w.id?styles.windowActive:""} onClick={()=>setWindowId(w.id)}><small>{w.label}</small><b>{w.start.slice(5)} → {w.end.slice(5)}</b><span>{w.note}</span><em>{w.reason}</em></button>)}</div></div>}<button className={styles.next} disabled={dateLoading||!selectedWindow} onClick={()=>setStage("reality")}>{say(lang,"Συνέχεια →","Continue →")}</button></section>}

  {stage==="reality"&&discovery&&selectedWindow&&<section className={styles.screen}><div className={styles.reality}><span className={styles.kicker}>04 · REALITY</span><h2>{say(lang,"Δύο πράγματα πριν ψάξω πραγματικά.","Two things before I search for real.")}</h2><div className={styles.realityGrid}><label>{say(lang,"Αφετηρία","Starting from")}<input value={origin} onChange={e=>setOrigin(e.target.value)}/></label><div><span>{say(lang,"Άνετο συνολικό budget","Comfortable total budget")}</span><div className={styles.budgets}>{[600,900,1200,1600,2200,3000].map(v=><button key={v} className={budget===v?styles.budgetActive:""} onClick={()=>setBudget(v)}>€{v}</button>)}</div></div></div><div className={styles.brief}><b>{discovery.summary}</b><span>{selectedWindow.start} → {selectedWindow.end} · {origin} · €{budget}</span></div><button className={styles.primary} disabled={busy||origin.trim().length<2} onClick={solve}>{say(lang,"Βρες 10 πραγματικές λύσεις →","Find 10 real solutions →")}</button></div></section>}

  {stage==="solve"&&<section className={styles.screen}><div className={styles.solve}><div className={styles.orbit}><i/><i/><i/><b>AI</b></div><span className={styles.kicker}>05 · BIDIRECTIONAL SEARCH</span><h2>{say(lang,"Δεν ψάχνω μόνο “πού ταιριάζεις”. Ελέγχω και τι μπορούμε πράγματι να σου προσφέρουμε.","I am not only asking where you fit. I am checking what we can actually offer you.")}</h2><div className={styles.agentLines}>{rows.slice(-5).map((row,i)=><p key={`${row.type}-${i}`}><span>{row.progress??"·"}</span>{row.message??row.type}</p>)}</div><small>Need → Destination → Stay ⇄ Stay Inventory → Destination → Need</small></div></section>}

  {stage==="results"&&selected&&selectedWindow&&<section className={`${styles.screen} ${styles.results}`}><button className={styles.prev} onClick={()=>move(-1)}>‹</button><button className={styles.nextResult} onClick={()=>move(1)}>›</button><div className={styles.resultMain}><div className={styles.resultStory}><span className={styles.kicker}>#{selected.rank} · {selected.combinedScore}% · {result?.sourceMode==="reverse-recovery"?"RECOVERED BY INVENTORY":"DUAL-PASS"}</span><h1>{lang==="en"?selected.recommendation.destinationEn:selected.recommendation.destination}</h1><p className={styles.why}>{selected.reasoning.destination}</p><div className={styles.scores}><span>{say(lang,"Destination","Destination")} <b>{selected.destinationScore}</b></span><span>{say(lang,"Stay","Stay")} <b>{selected.stayScore}</b></span><span>{say(lang,"Inventory","Inventory")} <b>{selected.inventoryCount}</b></span></div><div className={styles.reverse}><small>{say(lang,"ΑΝΤΙΣΤΡΟΦΗ ΣΚΕΨΗ","REVERSE REASONING")}</small><p>{selected.reasoning.reverse}</p></div></div><aside className={styles.stay}>{selected.stay.imageUrl&&<img src={selected.stay.imageUrl} alt=""/>}<div><small>{say(lang,"ΤΟ ΚΑΤΑΛΥΜΑ ΠΟΥ ΣΤΗΡΙΖΕΙ ΤΗΝ ΕΠΙΛΟΓΗ","THE STAY SUPPORTING THIS CHOICE")}</small><h3>{selected.stay.propertyName}</h3><p>{selected.reasoning.stay}</p><div className={styles.stayMetrics}><span>semantic <b>{selected.stay.semanticScore}</b></span><span>value <b>{selected.stay.valueScore}</b></span><span>location <b>{selected.stay.locationScore}</b></span></div>{selected.stay.price!=null&&<strong>{selected.stay.currency??"EUR"} {Math.round(selected.stay.price)} <small>{say(lang,"τιμή feed","feed price")}</small></strong>}<small className={styles.tradeoff}>{selected.reasoning.tradeoff}</small>{selected.alternatives.length>0&&<div className={styles.altStays}>{selected.alternatives.slice(0,3).map(x=><span key={x.sourceProductId}>{x.propertyName}</span>)}</div>}<div className={styles.ctas}><a className={styles.primaryLink} href={href(selected)}>{say(lang,"Χτίσε το 360° ταξίδι","Build the 360° trip")}</a><a className={styles.affiliate} href={selected.stay.trackingUrl} target="_blank" rel="sponsored noreferrer">{say(lang,"Δες το κατάλυμα ↗","Check the stay ↗")}</a></div></div></aside></div><div className={styles.rail}>{solutions.map((solution,index)=>{const thumb=solutionMedia[solution.recommendation.slug]?.[0]?.imageUrl??solution.stay.imageUrl;return <button key={`${solution.recommendation.slug}-${solution.stay.sourceProductId}`} className={index===solutionIndex?styles.railActive:""} onClick={()=>setSolutionIndex(index)}>{thumb&&<img src={thumb} alt=""/>}<i/><small>#{index+1}</small><b>{lang==="en"?solution.recommendation.destinationEn:solution.recommendation.destination}</b><span>{solution.stay.propertyName}</span></button>})}</div></section>}

  {error&&<div className={styles.error}>{error}<button onClick={()=>setError(null)}>×</button></div>}
 </main>
}

"use client";

import { FormEvent,useEffect,useMemo,useState } from "react";
import type { V8StayOffer } from "@/lib/decision/v8-types";
import type { TripRequest } from "@/lib/validation/trip";
import type { TripBuilderPlanV25 } from "@/lib/trip-builder/types-v25";
import type { LocalIntelligenceV38,LocalPlaceV38,GuestSignalV38 } from "@/lib/data/local-intelligence-v38";
import styles from "./v38-escape-builder.module.css";

type Lang="el"|"en";
type Stage="cinema"|"research"|"explore"|"stay"|"verify"|"email"|"unlocked";
type Media={imageUrl:string;originalUrl?:string;sourceUrl:string;title:string;description?:string;license:string;attribution:string};
type ResearchPlace={id?:string;name:string;summary?:string|null;whyItFits?:string|null};
type Dossier={
 release?:string;
 destination:{slug:string;name:string;nameEn:string;latitude:number;longitude:number;isSummer:boolean};
 weather:{label:string;score:number|null;days:Array<{date:string;temperatureMinC:number|null;temperatureMaxC:number|null;precipitationProbability?:number|null;summary:string}>};
 localIntelligence:LocalIntelligenceV38;
 research:{source:string;overview:string|null;attractions:ResearchPlace[];practicalNotes:string[];sources:Array<{title:string;url:string;domain:string}>};
 budgetBeyondHotel:{totalLow:number;totalHigh:number;note:string};
};
type Tab="highlights"|"eat"|"drinks"|"culture"|"sea"|"practical";

type Props={slug:string;name:string;nameEn:string;trip:TripRequest;offers:V8StayOffer[];lang?:Lang;missionId?:string|null};
const say=(lang:Lang,el:string,en:string)=>lang==="el"?el:en;
const providerPrice=(offer:V8StayOffer,lang:Lang)=>offer.price!=null&&offer.price>0?`${offer.price.toLocaleString(lang==="el"?"el-GR":"en-GB",{maximumFractionDigits:2})} ${offer.currency||"EUR"}`:say(lang,"Τιμή στον πάροχο","Price at provider");
const safeUrl=(value:unknown)=>typeof value==="string"&&/^https:\/\//i.test(value.trim())?value.trim():null;
function collectUrls(value:unknown,out:Set<string>,depth=0){if(depth>3||out.size>=10||value==null)return;if(typeof value==="string"){const direct=safeUrl(value);if(direct)out.add(direct);else for(const token of value.split(/[|,;\s]+/)){const url=safeUrl(token);if(url)out.add(url)}return}if(Array.isArray(value)){for(const item of value)collectUrls(item,out,depth+1);return}if(typeof value==="object"){for(const[key,item]of Object.entries(value as Record<string,unknown>)){if(/image|photo|picture|gallery|thumb|media/i.test(key))collectUrls(item,out,depth+1)}}}
function stayImages(offer:V8StayOffer|null){if(!offer)return[];const out=new Set<string>();for(const candidate of[offer.imageUrl,offer.thumbUrl]){const url=safeUrl(candidate);if(url)out.add(url)}collectUrls(offer.raw,out);return[...out].slice(0,8)}
function sourceBadge(place:LocalPlaceV38){return place.source==="Google Places"?"GOOGLE":place.source==="Foursquare"?"FOURSQUARE":place.source==="Tripadvisor"?"TRIPADVISOR":"OPEN DATA"}
function aiSignalText(signal:GuestSignalV38|null,lang:Lang){if(!signal||signal.aiScore==null||signal.sampleSize<3)return null;return say(lang,`AI Guest Signal ${signal.aiScore}/100 · ${signal.sampleSize} εμπειρίες`,`AI Guest Signal ${signal.aiScore}/100 · ${signal.sampleSize} experiences`)}
function placeSort(rows:LocalPlaceV38[]){return[...rows].sort((a,b)=>(b.internalSignal?.aiScore??-1)-(a.internalSignal?.aiScore??-1)||(b.rating??-1)-(a.rating??-1)||(b.ratingCount??0)-(a.ratingCount??0)).slice(0,8)}

export function V38EscapeBuilderClient({slug,name,nameEn,trip,offers,lang="el",missionId=null}:Props){
 const destination=lang==="en"?nameEn:name;
 const[selected,setSelected]=useState<V8StayOffer|null>(offers[0]??null),[dossier,setDossier]=useState<Dossier|null>(null),[plan,setPlan]=useState<TripBuilderPlanV25|null>(null),[stage,setStage]=useState<Stage>("cinema"),[tab,setTab]=useState<Tab>("highlights"),[busy,setBusy]=useState(false),[error,setError]=useState<string|null>(null);
 const[media,setMedia]=useState<Media[]>([]),[heroFrame,setHeroFrame]=useState(0),[stayFrame,setStayFrame]=useState(0),[email,setEmail]=useState(""),[mailState,setMailState]=useState<"idle"|"sending"|"sent"|"error">("idle");
 const[feedbackRating,setFeedbackRating]=useState(5),[feedbackRecommend,setFeedbackRecommend]=useState(true),[feedbackComment,setFeedbackComment]=useState(""),[feedbackState,setFeedbackState]=useState<"idle"|"sending"|"sent"|"error">("idle");
 const hero=media[heroFrame]?.imageUrl||selected?.imageUrl||selected?.thumbUrl||null,currentOffer=plan?.stay?.trackingUrl||selected?.trackingUrl||"",guideUrl=plan?.guide.path||"",selectedImages=useMemo(()=>stayImages(selected),[selected]),tripComplete=trip.endDate<=new Date().toISOString().slice(0,10);
 const weatherDays=useMemo(()=>dossier?.weather.days.slice(0,5)??[],[dossier]),local=dossier?.localIntelligence??null;
 const track=(eventName:string,payload:Record<string,unknown>={})=>{if(missionId)void fetch("/api/escape/event",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,eventName,payload})}).catch(()=>null)};

 useEffect(()=>{let cancelled=false;async function load(){const aerial=await fetch(`/api/escape/media?destination=${encodeURIComponent(nameEn||name)}&mode=aerial`).then(r=>r.ok?r.json():null).catch(()=>null) as {items?:Media[]}|null;let items=aerial?.items??[];if(!items.length){const normal=await fetch(`/api/escape/media?destination=${encodeURIComponent(nameEn||name)}`).then(r=>r.ok?r.json():null).catch(()=>null) as {items?:Media[]}|null;items=normal?.items??[]}if(!cancelled)setMedia(items.slice(0,6))}void load();return()=>{cancelled=true}},[name,nameEn]);
 useEffect(()=>{if(media.length<2)return;const timer=window.setInterval(()=>setHeroFrame(i=>(i+1)%media.length),6800);return()=>window.clearInterval(timer)},[media.length]);
 useEffect(()=>{setStayFrame(0);if(selectedImages.length<2)return;const timer=window.setInterval(()=>setStayFrame(i=>(i+1)%selectedImages.length),5200);return()=>window.clearInterval(timer)},[selected?.sourceProductId,selectedImages.length]);

 async function research(){setBusy(true);setError(null);setStage("research");track("v38_360_research_started",{destinationId:slug});try{if(missionId)await fetch("/api/escape/select",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationId:slug})}).catch(()=>null);const response=await fetch("/api/escape/research",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({trip,slug})});if(!response.ok)throw new Error(`research_${response.status}`);const data=await response.json() as Dossier;setDossier(data);setStage("explore");track("v38_360_research_completed",{destinationId:slug,providers:data.localIntelligence?.providers??[]})}catch{setError(say(lang,"Ο 360° έλεγχος δεν ολοκληρώθηκε. Η επιλογή σου έχει κρατηθεί — δεν θα γεμίσω τα κενά με εικασίες.","The 360° check did not complete. Your choice is saved — I will not fill gaps with guesses."));setStage("cinema")}finally{setBusy(false)}}
 async function verifyStay(){if(!selected)return;setBusy(true);setError(null);setStage("verify");track("stay_cinema_selected",{destinationId:slug,offerId:selected.sourceProductId});try{const response=await fetch("/api/trip-builder",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({trip,slug,offerId:selected.sourceProductId})});if(!response.ok)throw new Error(`builder_${response.status}`);const built=await response.json() as TripBuilderPlanV25;setPlan(built);setStage("email");if(missionId){const mediaRows=[built.stay?.imageUrl?{kind:"stay",url:built.stay.imageUrl}:null,...(local?.attractions??[]).slice(0,5).map(x=>x.imageUrl?{kind:"place",url:x.imageUrl,name:x.name}:null),...(local?.restaurants??[]).slice(0,5).map(x=>x.imageUrl?{kind:"restaurant",url:x.imageUrl,name:x.name}:null)].filter(Boolean).slice(0,20);void fetch("/api/escape/research/complete",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationId:slug,weather:built.weather,places:dossier?.research.attractions??[],restaurants:local?.restaurants??[],practicalNotes:dossier?.research.practicalNotes??[],logistics:{availability:built.availability,flexibleWindows:built.flexibleWindows,budgetBeyondHotel:built.budgetBeyondHotel},sources:dossier?.research.sources??[],media:mediaRows,guidePath:built.guide.path,trackingUrl:built.stay?.trackingUrl??selected.trackingUrl})}).catch(()=>null)}}catch{setError(say(lang,"Δεν μπόρεσα να επιβεβαιώσω αυτή τη διαμονή με ασφάλεια. Διάλεξε άλλη βάση — δεν θα εμφανίσω ψεύτικη διαθεσιμότητα.","I could not verify this stay safely. Choose another base — I will not show fake availability."));setStage("stay")}finally{setBusy(false)}}
 async function sendEmail(event:FormEvent){event.preventDefault();if(!selected||!plan||!email)return;setMailState("sending");try{const response=await fetch("/api/guide/email",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({email,slug,start:trip.startDate,end:trip.endDate,offer:selected.sourceProductId,language:lang})});if(!response.ok)throw new Error();if(missionId)await fetch("/api/escape/email-state",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,email})}).catch(()=>null);setMailState("sent");setStage("unlocked");track("email_gate_completed",{destinationId:slug,offerId:selected.sourceProductId})}catch{setMailState("error")}}
 async function share(){const url=window.location.href,text=say(lang,`Τι λες για ${destination}; Έφτιαξα μια 360° απόδραση για εμάς.`,`What do you think about ${destination}? I built a 360° escape for us.`);if(navigator.share)await navigator.share({title:destination,text,url}).catch(()=>undefined);else await navigator.clipboard.writeText(url).catch(()=>undefined);track("escape_shared",{destinationId:slug})}
 async function sendFeedback(event:FormEvent){event.preventDefault();if(!missionId||!tripComplete)return;setFeedbackState("sending");try{const response=await fetch("/api/escape/feedback",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({missionId,destinationSlug:slug,subjectKind:"destination",subjectKey:`destination:${slug}`,subjectName:destination,went:true,rating:feedbackRating,wouldRecommend:feedbackRecommend,comment:feedbackComment})});if(!response.ok)throw new Error();setFeedbackState("sent")}catch{setFeedbackState("error")}}

 const tabs:Array<{id:Tab;el:string;en:string;count:number}>=[
  {id:"highlights",el:"Μη χάσεις",en:"Don't miss",count:(local?.attractions.length??0)},
  {id:"eat",el:"Φαγητό",en:"Eat",count:(local?.restaurants.length??0)},
  {id:"drinks",el:"Ποτό & βράδυ",en:"Drinks & nights",count:(local?.nightlife.length??0)},
  {id:"culture",el:"Κουλτούρα",en:"Culture",count:(local?.museums.length??0)},
  {id:"sea",el:"Θάλασσα",en:"Sea",count:(local?.beaches.length??0)},
  {id:"practical",el:"Πριν φύγεις",en:"Know before",count:dossier?.research.practicalNotes.length??0},
 ];
 const activePlaces=tab==="highlights"?placeSort(local?.attractions??[]):tab==="eat"?placeSort(local?.restaurants??[]):tab==="drinks"?placeSort(local?.nightlife??[]):tab==="culture"?placeSort(local?.museums??[]):tab==="sea"?placeSort(local?.beaches??[]):[];
 const guestDestination=aiSignalText(local?.destinationSignal??null,lang);

 return <main className={styles.shell}>
  <header className={styles.topbar}><a href={lang==="en"?"/en":"/"} className={styles.brand}><span>AI</span> ESCAPE STUDIO</a><div className={styles.journey}>{(["cinema","explore","stay","email","unlocked"] as Stage[]).map((s,i)=><span key={s} className={stage===s||(["research"].includes(stage)&&s==="cinema")||(["verify"].includes(stage)&&s==="stay")?styles.activeStep:""}>{String(i+1).padStart(2,"0")}</span>)}</div><button type="button" onClick={share} className={styles.share}>{say(lang,"Μοιράσου","Share")}</button></header>

  <section className={styles.hero}>
   <div className={styles.heroFrames}>{media.map((item,index)=><figure key={item.imageUrl} className={`${styles.heroFrame} ${index===heroFrame?styles.heroFrameActive:""}`}><img src={item.imageUrl} alt={item.title}/></figure>)}{!media.length&&hero?<figure className={`${styles.heroFrame} ${styles.heroFrameActive}`}><img src={hero} alt={destination}/></figure>:null}</div>
   <div className={styles.heroShade}/><div className={styles.grain}/>
   <div className={styles.heroCopy}><span className={styles.eyebrow}>YOUR ESCAPE · {trip.startDate} → {trip.endDate}</span><h1>{destination}</h1><p>{say(lang,"Δεν θα σου πουλήσω δωμάτιο πριν καταλάβεις το μέρος. Πρώτα κάνουμε 360° έλεγχο: καιρός, τι αξίζει, πού τρώνε καλά, πού βγαίνεις, τι να αποφύγεις — και μόνο μετά διαμονή.","I will not sell you a room before you understand the place. First comes a 360° check: weather, what matters, where to eat, where to go out, what to avoid — then the stay.")}</p><div className={styles.heroActions}>{stage==="cinema"?<button type="button" onClick={research} disabled={busy}>{say(lang,"Χτίσε μου την απόδραση 360° →","Build my 360° escape →")}</button>:<a href="#escape360">{say(lang,"Άνοιξε το dossier ↓","Open the dossier ↓")}</a>}<span>{say(lang,"Πραγματικές πηγές · καθόλου fake ratings","Real sources · zero fake ratings")}</span></div></div>
   {media[heroFrame]?<div className={styles.mediaCredit}><strong>{/\b(drone|aerial|bird)/i.test(`${media[heroFrame].title} ${media[heroFrame].description??""}`)?say(lang,"AERIAL SOURCE","AERIAL SOURCE"):say(lang,"CINEMATIC SOURCE","CINEMATIC SOURCE")}</strong><span>{media[heroFrame].attribution} · {media[heroFrame].license}</span></div>:null}
